#!/usr/bin/env bash
# Batch driver of the 2026-10-08 directive (DX_PREREG.md): every lifecycle of
# ORDER_FILE in its preregistered order, streaming, one server per lifecycle.
#
#   run_dx.sh <RUN_DIR_ABS> <ORDER_FILE_ABS>
#
# ORDER_FILE: {"order": [{"seq", "tag", "config", "plan_id", "obs", "eval_s"}]}.
# After each lifecycle only its validity is checked (dx_check.py; no outcome is
# printed). An INVALID lifecycle is rerun once with the same plan under
# "<tag>.retry1"; a second INVALID is left as it is. Resumable (a tag with a
# done marker and a valid check is skipped). Do not edit this file,
# run_dx_lifecycle.sh, dx_check.py, dx_steps.py or the runner while it runs
# (KNOWN_PITFALLS 5).
set -uo pipefail
RUN="$1"; ORDER="$2"
REPO=/home/rebel/continuum-npu
for p in "$RUN" "$ORDER"; do case "$p" in /*) ;; *) echo "path must be absolute: $p"; exit 64 ;; esac; done
mkdir -p "$RUN"
S3="$REPO/experiments/npu/stage3"
PLANS="$S3/plans/dx"
declare -A ART=(
  [BASE]="$REPO/models/Qwen3-4B-rbln-b8-s8192-d4-mb"
  [BATCHONLY]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-batchonly"
  [TUNED]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-mb16"
  [DP_N8]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-dp8"
)
for c in "${!ART[@]}"; do [ -f "${ART[$c]}/rbln_config.json" ] || { echo "missing artifact $c"; exit 2; }; done

git -C "$REPO" rev-parse HEAD >> "$RUN/git-head.txt"
git -C "$REPO" status --porcelain >> "$RUN/git-status.txt"
sha256sum "$ORDER" >> "$RUN/order-sha256.txt"
[ -f "$RUN/measurement-start.txt" ] || date -Is > "$RUN/measurement-start.txt"
rbln-stat > "$RUN/rbln-stat-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply_steptime.sh" status > "$RUN/patch-steptime-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply_steptime_v2.sh" status > "$RUN/patch-steptime-v2-before.$(date +%s).txt" 2>&1

mapfile -t ITEMS < <(python3 -c "
import json
for e in json.load(open('$ORDER'))['order']:
    print(e['seq'], e['tag'], e['config'], e['plan_id'], e['obs'], e.get('eval_s', ''))")

one() {  # seq tag config plan_id obs eval_s
  local SEQ="$1" TAG="$2" CFG="$3" PID="$4" OBS="$5" EV="${6:-}"
  echo "=== [$SEQ] $TAG obs=$OBS $(date -Is)"
  bash "$S3/run_dx_lifecycle.sh" "$RUN" "$TAG" "${ART[$CFG]}" "$PLANS/$PID.json" stream "$OBS" $EV
  env -u PYTHONPATH python3 "$S3/dx_check.py" --run "$RUN" --tag "$TAG" --config "$CFG" \
    --plan-id "$PID" > "$RUN/check.$TAG.json" 2> "$RUN/check.$TAG.err"
  local RC=$?
  cat "$RUN/check.$TAG.json" >> "$RUN/checks.jsonl"
  if [ "$RC" -eq 0 ]; then echo "[$SEQ] $TAG VALID"; else echo "[$SEQ] $TAG INVALID"; fi
  return $RC
}

for item in "${ITEMS[@]}"; do
  set -- $item
  SEQ="$1"; TAG="$2"; CFG="$3"; PID="$4"; OBS="$5"; EV="${6:-}"
  if [ -f "$RUN/check.$TAG.json" ] && [ -f "$RUN/done.$TAG" ] && \
     python3 -c "import json,sys; sys.exit(0 if json.load(open('$RUN/check.$TAG.json'))['valid'] else 1)"; then
    echo "[$SEQ] $TAG already valid, skipping"; continue
  fi
  if [ -f "$RUN/check.$TAG.json" ] && [ -f "$RUN/check.$TAG.retry1.json" ]; then
    echo "[$SEQ] $TAG already retried, skipping"; continue
  fi
  if [ ! -f "$RUN/check.$TAG.json" ]; then
    one "$SEQ" "$TAG" "$CFG" "$PID" "$OBS" "$EV" && continue
  fi
  one "$SEQ" "$TAG.retry1" "$CFG" "$PID" "$OBS" "$EV"
done

date -Is > "$RUN/measurement-end.txt"
rbln-stat > "$RUN/rbln-stat-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply_steptime.sh" status > "$RUN/patch-steptime-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply_steptime_v2.sh" status > "$RUN/patch-steptime-v2-after.txt" 2>&1
echo "DX DONE"
